insert into public.exercises (name, muscle_group, equipment, log_type, cues) values
  ('Yoga session (full practice)', 'Yoga', 'Mat', 'timed', 'Log the whole class or practice as one entry. Move with your breath and rest in Child''s pose whenever you need.'),
  ('Surya Namaskar (Sun Salutation)', 'Yoga', 'Mat', 'timed', 'Flow through the 12 steps with the breath: inhale to lift and open, exhale to fold and lower. Keep the movements smooth; one round on each leg makes a full set.'),
  ('Tadasana (Mountain pose)', 'Yoga', 'Mat', 'timed', 'Stand tall, feet together or hip-width, weight even on both feet. Lengthen the spine, relax the shoulders, breathe slowly.'),
  ('Vrikshasana (Tree pose)', 'Yoga', 'Mat', 'timed', 'Place one foot on the inner calf or thigh (never on the knee). Hands at the chest or overhead, gaze at a fixed point. Change sides.'),
  ('Trikonasana (Triangle pose)', 'Yoga', 'Mat', 'timed', 'Feet wide, front foot turned out. Reach forward, then lower the hand to the shin or a block, top arm up. Keep both sides of the waist long. Change sides.'),
  ('Virabhadrasana I (Warrior I)', 'Yoga', 'Mat', 'timed', 'Long stance, front knee over the ankle, back heel down at an angle. Hips face forward, arms reach up. Change sides.'),
  ('Virabhadrasana II (Warrior II)', 'Yoga', 'Mat', 'timed', 'Wide stance, front knee over the ankle, arms stretched out at shoulder height, gaze over the front hand. Change sides.'),
  ('Utkatasana (Chair pose)', 'Yoga', 'Mat', 'timed', 'Feet together, sit back as if into a chair, arms up beside the ears. Keep the weight in the heels and the chest lifted.'),
  ('Adho Mukha Svanasana (Downward dog)', 'Yoga', 'Mat', 'timed', 'Hands shoulder-width, hips up and back into an upside-down V. Bend the knees if the back rounds; press the floor away.'),
  ('Bhujangasana (Cobra pose)', 'Yoga', 'Mat', 'timed', 'Lie face down, hands under the shoulders. Lift the chest gently using the back, elbows close to the body, hips stay down.'),
  ('Marjariasana–Bitilasana (Cat–cow)', 'Yoga', 'Mat', 'timed', 'On hands and knees: inhale, drop the belly and lift the chest; exhale, round the back. Move slowly with the breath.'),
  ('Balasana (Child''s pose)', 'Yoga', 'Mat', 'timed', 'Knees apart or together, sit back towards the heels, forehead down, arms forward or by the sides. Breathe into the back.'),
  ('Setu Bandhasana (Bridge pose)', 'Yoga', 'Mat', 'timed', 'Lie on your back, knees bent, feet hip-width. Press through the feet to lift the hips; keep knees in line with the feet.'),
  ('Naukasana (Boat pose)', 'Yoga', 'Mat', 'timed', 'Sit, lean back with a long spine, lift the feet (knees bent to start). Arms forward. Keep the chest lifted, not rounded.'),
  ('Dhanurasana (Bow pose)', 'Yoga', 'Mat', 'timed', 'Lie face down, bend the knees and hold the ankles. Press the feet back to lift the chest and thighs. Ease in slowly.'),
  ('Paschimottanasana (Seated forward bend)', 'Yoga', 'Mat', 'timed', 'Sit with legs straight, lengthen up, then fold forward from the hips. Bend the knees as much as needed; do not force.'),
  ('Baddha Konasana (Butterfly pose)', 'Yoga', 'Mat', 'timed', 'Sit, soles of the feet together, knees out. Hold the feet, sit tall and let the knees relax down.'),
  ('Ardha Matsyendrasana (Seated twist)', 'Yoga', 'Mat', 'timed', 'Sit tall, cross one foot over the other knee, twist towards the bent knee using the breath. Lengthen on inhale, twist on exhale. Change sides.'),
  ('Anulom Vilom (Alternate nostril breathing)', 'Yoga', 'None', 'timed', 'Sit comfortably with a straight back. Breathe in through one nostril and out through the other, then switch. Slow, easy breaths – never strain.'),
  ('Shavasana (Relaxation)', 'Yoga', 'Mat', 'timed', 'Lie on your back, arms by your sides, eyes closed. Let the whole body relax and breathe naturally for a few minutes.');
